//! Support for code generated by `ras-jsonrpc-bidirectional-macro`.
//!
//! Not public API. The generated client code names its dependencies through this module, so an
//! API crate needs only this crate and `serde` for its own derives. Anything here may change in
//! any release.

use crate::{Client, ClientError, NotificationHandler, RpcRequestHandler, error::ClientResult};
use ras_jsonrpc_types::{JsonRpcError, JsonRpcRequest, JsonRpcResponse};
use serde::{Serialize, de::DeserializeOwned};
use std::future::Future;
use std::sync::Arc;

pub use ras_jsonrpc_types;
pub use serde;
pub use serde_json;
pub use tokio;

/// Call `method` on the server and decode its result.
pub async fn call_method<P: Serialize, R: DeserializeOwned>(
    client: &Client,
    method: &str,
    params: P,
) -> ClientResult<R> {
    let response = client
        .call(method, Some(serde_json::to_value(params)?))
        .await?;
    match (response.result, response.error) {
        (_, Some(error)) => Err(ClientError::Rpc(error)),
        (Some(result), None) => Ok(serde_json::from_value(result)?),
        (None, None) => Err(ClientError::internal("Response has no result or error")),
    }
}

/// Wrap a typed notification callback as a [`NotificationHandler`].
///
/// Params that do not decode are logged and dropped.
pub fn notification_handler<P, F>(method: &'static str, handler: F) -> NotificationHandler
where
    P: DeserializeOwned,
    F: Fn(P) + Send + Sync + 'static,
{
    Arc::new(move |received: &str, params: &serde_json::Value| {
        if received != method {
            return;
        }
        match serde_json::from_value::<P>(params.clone()) {
            Ok(params) => handler(params),
            Err(e) => tracing::warn!(method, "dropping notification with bad params: {e}"),
        }
    })
}

/// Wrap a typed callback for a server-to-client call as an [`RpcRequestHandler`].
///
/// Params that do not decode are answered with `-32602`, and an `Err` from the callback with
/// `-32000` and the string as the message.
pub fn rpc_handler<Req, Resp, F, Fut>(handler: F) -> RpcRequestHandler
where
    Req: DeserializeOwned + Send + 'static,
    Resp: Serialize + Send + 'static,
    F: Fn(Req) -> Fut + Send + Sync + 'static,
    Fut: Future<Output = Result<Resp, String>> + Send + 'static,
{
    let handler = Arc::new(handler);
    Arc::new(move |request: JsonRpcRequest| {
        let handler = handler.clone();
        Box::pin(async move {
            let params = request.params.unwrap_or(serde_json::Value::Null);
            let params: Req = match serde_json::from_value(params) {
                Ok(params) => params,
                Err(e) => {
                    return JsonRpcResponse::error(
                        JsonRpcError::new(-32602, format!("Invalid params: {e}"), None),
                        request.id,
                    );
                }
            };
            match handler(params).await {
                Ok(result) => match serde_json::to_value(result) {
                    Ok(value) => JsonRpcResponse::success(value, request.id),
                    Err(e) => JsonRpcResponse::error(
                        JsonRpcError::new(-32603, format!("Failed to serialize result: {e}"), None),
                        request.id,
                    ),
                },
                Err(message) => {
                    JsonRpcResponse::error(JsonRpcError::new(-32000, message, None), request.id)
                }
            }
        })
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn rpc_handler_answers_bad_params_with_invalid_params() {
        let handler = rpc_handler(|value: u32| async move { Ok::<_, String>(value + 1) });

        let ok = handler(JsonRpcRequest::new(
            "inc".into(),
            Some(serde_json::json!(1)),
            Some(1.into()),
        ))
        .await;
        assert_eq!(ok.result, Some(serde_json::json!(2)));

        let bad = handler(JsonRpcRequest::new(
            "inc".into(),
            Some(serde_json::json!("x")),
            Some(2.into()),
        ))
        .await;
        assert_eq!(bad.error.unwrap().code, -32602);
    }

    #[test]
    fn notification_handler_ignores_other_methods_and_bad_params() {
        let seen = Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let handler = notification_handler("tick", move |n: u32| sink.lock().unwrap().push(n));

        handler("tick", &serde_json::json!(3));
        handler("tock", &serde_json::json!(4));
        handler("tick", &serde_json::json!("bad"));
        assert_eq!(*seen.lock().unwrap(), vec![3]);
    }
}
